  1→package main
  2→
  3→import (
  4→	"context"
  5→	"encoding/json"
  6→	"flag"
  7→	"fmt"
  8→	"log"
  9→	"os"
 10→	"regexp"
 11→	"time"
 12→
 13→	"go.mongodb.org/mongo-driver/bson"
 14→	"go.mongodb.org/mongo-driver/mongo"
 15→	"go.mongodb.org/mongo-driver/mongo/options"
 16→)
 17→
 18→type AnytypeDB struct {
 19→	client        *mongo.Client
 20→	coordinatorDB *mongo.Database
 21→	consensusDB   *mongo.Database
 22→	mongoURL      string
 23→}
 24→
 25→// Connect to MongoDB
 26→func New(mongoURL string) (*AnytypeDB, error) {
 27→	if mongoURL == "" {
 28→		mongoURL = "mongodb://127.0.0.1:27017"
 29→	}
 30→
 31→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
 32→	defer cancel()
 33→
 34→	client, err := mongo.Connect(ctx, options.Client().ApplyURI(mongoURL))
 35→	if err != nil {
 36→		return nil, err
 37→	}
 38→
 39→	// Test connection
 40→	err = client.Ping(ctx, nil)
 41→	if err != nil {
 42→		return nil, err
 43→	}
 44→
 45→	return &AnytypeDB{
 46→		client:        client,
 47→		coordinatorDB: client.Database("coordinator"),
 48→		consensusDB:   client.Database("consensus"),
 49→		mongoURL:      mongoURL,
 50→	}, nil
 51→}
 52→
 53→// Disconnect from MongoDB
 54→func (a *AnytypeDB) Disconnect() error {
 55→	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
 56→	defer cancel()
 57→	return a.client.Disconnect(ctx)
 58→}
 59→
 60→// List all spaces
 61→func (a *AnytypeDB) ListSpaces() ([]bson.M, error) {
 62→	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
 63→	defer cancel()
 64→
 65→	coll := a.coordinatorDB.Collection("spaces")
 66→	cursor, err := coll.Find(ctx, bson.D{})
 67→	if err != nil {
 68→		return nil, err
 69→	}
 70→	defer cursor.Close(ctx)
 71→
 72→	var spaces []bson.M
 73→	if err = cursor.All(ctx, &spaces); err != nil {
 74→		return nil, err
 75→	}
 76→
 77→	return spaces, nil
 78→}
 79→
 80→// Get space by ID
 81→func (a *AnytypeDB) GetSpace(spaceID string) (bson.M, error) {
 82→	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
 83→	defer cancel()
 84→
 85→	coll := a.coordinatorDB.Collection("spaces")
 86→	var space bson.M
 87→	err := coll.FindOne(ctx, bson.M{"_id": spaceID}).Decode(&space)
 88→	return space, err
 89→}
 90→
 91→// Get payloads by space
 92→func (a *AnytypeDB) GetPayloadsBySpace(spaceID string) ([]bson.M, error) {
 93→	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
 94→	defer cancel()
 95→
 96→	coll := a.consensusDB.Collection("payload")
 97→	
 98→	// Match IDs that start with spaceID/
 99→	filter := bson.M{
100→		"_id": bson.M{
101→			"$regex": "^" + regexp.QuoteMeta(spaceID) + "/",
102→		},
103→	}
104→
105→	cursor, err := coll.Find(ctx, filter)
106→	if err != nil {
107→		return nil, err
108→	}
109→	defer cursor.Close(ctx)
110→
111→	var payloads []bson.M
112→	if err = cursor.All(ctx, &payloads); err != nil {
113→		return nil, err
114→	}
115→
116→	return payloads, nil
117→}
118→
119→// Count payloads
120→func (a *AnytypeDB) CountPayloads(spaceID string) (int64, error) {
121→	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
122→	defer cancel()
123→
124→	coll := a.consensusDB.Collection("payload")
125→	
126→	if spaceID == "" {
127→		return coll.EstimatedDocumentCount(ctx)
128→	}
129→
130→	filter := bson.M{
131→		"_id": bson.M{
132→			"$regex": "^" + regexp.QuoteMeta(spaceID) + "/",
133→		},
134→	}
135→	return coll.CountDocuments(ctx, filter)
136→}
137→
138→// Get recent activity
139→func (a *AnytypeDB) GetRecentActivity(spaceID string, limit int) ([]bson.M, error) {
140→	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
141→	defer cancel()
142→
143→	coll := a.coordinatorDB.Collection("inboxMessages")
144→	
145→	filter := bson.M{}
146→	if spaceID != "" {
147→		filter["spaceId"] = spaceID
148→	}
149→
150→	opts := options.Find().SetSort(bson.M{"createdAt": -1}).SetLimit(int64(limit))
151→	cursor, err := coll.Find(ctx, filter, opts)
152→	if err != nil {
153→		return nil, err
154→	}
155→	defer cursor.Close(ctx)
156→
157→	var activity []bson.M
158→	if err = cursor.All(ctx, &activity); err != nil {
159→		return nil, err
160→	}
161→
162→	return activity, nil
163→}
164→
165→// Get space summary
166→func (a *AnytypeDB) GetSpaceSummary(spaceID string) (map[string]interface{}, error) {
167→	count, err := a.CountPayloads(spaceID)
168→	if err != nil {
169→		return nil, err
170→	}
171→
172→	activity, err := a.GetRecentActivity(spaceID, 5)
173→	if err != nil {
174→		return nil, err
175→	}
176→
177→	var lastUpdated interface{}
178→	if len(activity) > 0 {
179→		lastUpdated = activity[0]["createdAt"]
180→	}
181→
182→	return map[string]interface{}{
183→		"spaceId":       spaceID,
184→		"totalObjects":  count,
185→		"recentActivity": activity,
186→		"lastUpdated":   lastUpdated,
187→	}, nil
188→}
189→
190→// Main CLI
191→func main() {
192→	mongoURL := flag.String("mongo", os.Getenv("MONGODB_URL"), "MongoDB URL")
193→	help := flag.Bool("help", false, "Show help")
194→	flag.Parse()
195→
196→	if *help || len(os.Args) < 2 {
197→		printHelp()
198→		os.Exit(0)
199→	}
200→
201→	// Default to local if not set
202→	if *mongoURL == "" {
203→		*mongoURL = "mongodb://127.0.0.1:27017"
204→	}
205→
206→	db, err := New(*mongoURL)
207→	if err != nil {
208→		log.Fatalf("Failed to connect: %v", err)
209→	}
210→	defer db.Disconnect()
211→
212→	fmt.Println("✓ Connected to AnyType MongoDB")
213→
214→	command := flag.Args()[0]
215→	args := flag.Args()[1:]
216→
217→	switch command {
218→	case "spaces":
219→		cmdSpaces(db)
220→	case "space":
221→		if len(args) == 0 {
222→			log.Fatal("Space ID required")
223→		}
224→		cmdSpace(db, args[0])
225→	case "payloads":
226→		cmdPayloads(db)
227→	case "payloads-space":
