  1→#!/usr/bin/env node
  2→
  3→/**
  4→ * OpenClaw Session Sync for AnyType
  5→ * 
  6→ * Syncs OpenClaw session notes and conversation history to AnyType.
  7→ * 
  8→ * Usage:
  9→ *   node sync-notes.js --sessionKey main --type backup
 10→ *   node sync-notes.js --continuous [--interval 1800000]
 11→ *   node sync-notes.js --export markdown --output notes.md
 12→ */
 13→
 14→const fs = require('fs');
 15→const path = require('path');
 16→const { createClient } = require('./anytype-api.js');
 17→
 18→class SessionSync {
 19→  constructor(config = {}) {
 20→    this.config = {
 21→      sessionKey: config.sessionKey || process.env.OPENCLAW_SESSION_KEY || 'main',
 22→      sessionDir: config.sessionDir || process.env.OPENCLAW_SESSION_DIR || 
 23→                  path.join(process.env.HOME || '.', '.openclaw', 'workspace'),
 24→      anyTypeConfig: {
 25→        apiUrl: config.apiUrl || process.env.ANYTYPE_API_URL || 'http://127.0.0.1:31012',
 26→        apiKey: config.apiKey || process.env.ANYTYPE_API_KEY || '',
 27→        spaceId: config.spaceId || process.env.ANYTYPE_SPACE_ID || ''
 28→      },
 29→      pageTitle: config.pageTitle || this.generatePageTitle(),
 30→      tags: config.tags || ['openclaw', 'session', 'backup'],
 31→      batchSize: config.batchSize || 100,
 32→      continuous: config.continuous || false,
 33→      interval: config.interval || 1800000, // 30 minutes default
 34→      verbose: config.verbose || false
 35→    };
 36→
 37→    this.client = null;
 38→  }
 39→
 40→  log(msg, level = 'info') {
 41→    if (this.config.verbose || level !== 'debug') {
 42→      console.log(`[${new Date().toISOString()}] [${level.toUpperCase()}] ${msg}`);
 43→    }
 44→  }
 45→
 46→  generatePageTitle() {
 47→    const now = new Date();
 48→    return `OpenClaw Session - ${now.toISOString().split('T')[0]} ${now.toLocaleTimeString()}`;
 49→  }
 50→
 51→  /**
 52→   * Read OpenClaw session history from files
 53→   */
 54→  readSessionHistory() {
 55→    this.log('Reading session history...');
 56→
 57→    try {
 58→      // Read memory files if they exist
 59→      const memoryPath = path.join(this.config.sessionDir, 'MEMORY.md');
 60→      const dailyPath = path.join(this.config.sessionDir, 'memory', 
 61→        new Date().toISOString().split('T')[0] + '.md');
 62→
 63→      let content = '# OpenClaw Session Notes\n\n';
 64→      content += `**Session:** ${this.config.sessionKey}\n`;
 65→      content += `**Created:** ${new Date().toISOString()}\n`;
 66→      content += `**Hostname:** ${require('os').hostname()}\n\n`;
 67→
 68→      // Add memory if exists
 69→      if (fs.existsSync(memoryPath)) {
 70→        this.log('Found MEMORY.md');
 71→        const memory = fs.readFileSync(memoryPath, 'utf8');
 72→        content += `## Long-term Memory\n\n${memory}\n\n`;
 73→      }
 74→
 75→      // Add daily notes if exist
 76→      if (fs.existsSync(dailyPath)) {
 77→        this.log(`Found daily notes for today`);
 78→        const daily = fs.readFileSync(dailyPath, 'utf8');
 79→        content += `## Today's Notes\n\n${daily}\n\n`;
 80→      }
 81→
 82→      // Add current environment/status
 83→      content += `## System Info\n\n`;
 84→      content += `- Node version: ${process.version}\n`;
 85→      content += `- Platform: ${process.platform}\n`;
 86→      content += `- Working directory: ${process.cwd()}\n`;
 87→      content += `- Home directory: ${process.env.HOME || 'N/A'}\n\n`;
 88→
 89→      this.log(`Read ${content.length} characters of content`);
 90→      return content;
 91→    } catch (error) {
 92→      this.log(`Error reading session history: ${error.message}`, 'error');
 93→      throw error;
 94→    }
 95→  }
 96→
 97→  /**
 98→   * Initialize AnyType client
 99→   */
100→  initializeClient() {
101→    try {
102→      this.client = createClient(this.config.anyTypeConfig);
103→      this.log('AnyType client initialized');
104→    } catch (error) {
105→      this.log(`Failed to initialize client: ${error.message}`, 'error');
106→      throw error;
107→    }
108→  }
109→
110→  /**
111→   * Sync session to AnyType as new page
112→   */
113→  async syncAsNewPage() {
114→    this.log('Creating new session page in AnyType...');
115→
116→    try {
117→      const content = this.readSessionHistory();
118→
119→      const result = await this.client.createPage({
120→        title: this.config.pageTitle,
121→        content: content,
122→        tags: this.config.tags,
123→        type: 'page'
124→      });
125→
126→      this.log(`Successfully created page: ${result.id}`);
127→      return result;
128→    } catch (error) {
129→      this.log(`Failed to sync as new page: ${error.message}`, 'error');
130→      throw error;
131→    }
132→  }
133→
134→  /**
135→   * Sync session to existing page (append)
136→   */
137→  async syncToExistingPage(pageId) {
138→    this.log(`Appending to existing page: ${pageId}`);
139→
140→    try {
141→      const content = this.readSessionHistory();
142→
143→      const result = await this.client.appendContent({
144→        pageId: pageId,
145→        content: content
146→      });
147→
148→      this.log(`Successfully updated page: ${pageId}`);
149→      return result;
150→    } catch (error) {
151→      this.log(`Failed to sync to existing page: ${error.message}`, 'error');
152→      throw error;
153→    }
154→  }
155→
156→  /**
157→   * Export session as markdown file
158→   */
159→  async exportAsMarkdown(outputPath) {
160→    this.log(`Exporting session to ${outputPath}...`);
161→
162→    try {
163→      const content = this.readSessionHistory();
164→      fs.writeFileSync(outputPath, content, 'utf8');
165→      this.log(`Successfully exported to ${outputPath}`);
166→      return { path: outputPath, size: content.length };
167→    } catch (error) {
168→      this.log(`Failed to export: ${error.message}`, 'error');
169→      throw error;
170→    }
171→  }
172→
173→  /**
174→   * Run continuous sync mode
175→   */
176→  async runContinuous() {
177→    this.log(`Starting continuous sync (interval: ${this.config.interval}ms)`);
178→    
179→    // Initial sync
180→    await this.syncAsNewPage();
181→
182→    // Periodic syncs
183→    setInterval(async () => {
184→      try {
185→        this.log('Running periodic sync...');
186→        await this.syncAsNewPage();
187→      } catch (error) {
188→        this.log(`Periodic sync failed: ${error.message}`, 'error');
189→      }
190→    }, this.config.interval);
191→
192→    // Keep process alive
193→    process.on('SIGTERM', () => {
194→      this.log('Received SIGTERM, gracefully shutting down...');
195→      process.exit(0);
196→    });
197→  }
198→
199→  /**
200→   * Find most recent session page
201→   */
202→  async findRecentSession() {
203→    this.log('Searching for recent session pages...');
204→
205→    try {
206→      const results = await this.client.queryPages({
207→        query: 'openclaw',
208→        limit: 1,
209→        tags: ['openclaw']
210→      });
211→
212→      if (results.objects && results.objects.length > 0) {
213→        this.log(`Found recent session: ${results.objects[0].id}`);
214→        return results.objects[0];
215→      }
216→
217→      this.log('No recent sessions found');
218→      return null;
219→    } catch (error) {
220→      this.log(`Error finding recent session: ${error.message}`, 'error');
221→      return null;
222→    }
223→  }
224→}
