228→ */
229→async function cliMain() {
230→  const args = process.argv.slice(2);
231→  const config = {};
232→
233→  // Parse CLI arguments
234→  for (let i = 0; i < args.length; i += 2) {
235→    const key = args[i].replace(/^--/, '');
