282→
283→Environment variables:
284→  OPENCLAW_SESSION_KEY
285→  OPENCLAW_SESSION_DIR
286→  ANYTYPE_API_URL
287→  ANYTYPE_API_KEY
288→  ANYTYPE_SPACE_ID
289→        `);
290→        process.exit(0);
291→    }
292→  }
293→
294→  try {
