  1→#!/usr/bin/env node
  2→
  3→/**
  4→ * AnyType → PostgreSQL Monitor & Sync
  5→ * 
  6→ * Monitors AnyType space SQLite databases for changes
  7→ * Syncs new/updated objects to PostgreSQL
  8→ * Enables OpenClaw to query and act on workspace data
  9→ * 
 10→ * Usage:
 11→ *   node anytype-monitor.js --spaceId xxx --pgUrl postgres://... --watch
 12→ *   node anytype-monitor.js --list-spaces  (discover spaces)
 13→ *   node anytype-monitor.js --sync-now     (one-time sync)
 14→ */
 15→
 16→const fs = require('fs');
 17→const path = require('path');
 18→const sqlite3 = require('sqlite3');
 19→const pg = require('pg');
 20→const crypto = require('crypto');
 21→
 22→class AnytypeMonitor {
 23→  constructor(config = {}) {
 24→    this.config = {
 25→      accountDir: config.accountDir || path.join(
 26→        process.env.HOME || '.',
 27→        '.config/anytype/data',
 28→        config.accountId || process.env.ANYTYPE_ACCOUNT_ID || ''
 29→      ),
 30→      spaceId: config.spaceId || process.env.ANYTYPE_SPACE_ID || '',
 31→      pgUrl: config.pgUrl || process.env.DATABASE_URL || 'postgresql://localhost/openclaw',
 32→      pollInterval: config.pollInterval || 60000, // 60 seconds
 33→      verbose: config.verbose || false,
 34→      objectStoreDir: null,
 35→      spaceDbPath: null
 36→    };
 37→
 38→    this.setupPaths();
 39→    this.pgPool = null;
 40→    this.spaceDb = null;
 41→    this.lastSyncTime = {};
 42→  }
 43→
 44→  log(msg, level = 'info') {
 45→    if (this.config.verbose || level !== 'debug') {
 46→      console.log(`[${new Date().toISOString()}] [${level.toUpperCase()}] ${msg}`);
 47→    }
 48→  }
 49→
 50→  /**
 51→   * Setup file paths
 52→   */
 53→  setupPaths() {
 54→    this.config.objectStoreDir = path.join(this.config.accountDir, 'objectstore');
 55→    
 56→    if (this.config.spaceId) {
 57→      this.config.spaceDbPath = path.join(
 58→        this.config.objectStoreDir,
 59→        this.config.spaceId,
 60→        'objects.db'
 61→      );
 62→    }
 63→
 64→    this.log(`Account dir: ${this.config.accountDir}`);
 65→    if (this.config.spaceDbPath) {
 66→      this.log(`Space DB: ${this.config.spaceDbPath}`);
 67→    }
 68→  }
 69→
 70→  /**
 71→   * Initialize PostgreSQL connection
 72→   */
 73→  async initPostgres() {
 74→    this.log('Connecting to PostgreSQL...');
 75→    this.pgPool = new pg.Pool({ connectionString: this.config.pgUrl });
 76→    
 77→    // Test connection
 78→    const client = await this.pgPool.connect();
 79→    this.log('✓ Connected to PostgreSQL');
 80→    client.release();
 81→
 82→    // Create tables if needed
 83→    await this.createTables();
 84→  }
 85→
 86→  /**
 87→   * Create PostgreSQL tables for AnyType data
 88→   */
 89→  async createTables() {
 90→    const client = await this.pgPool.connect();
 91→    
 92→    try {
 93→      await client.query(`
 94→        CREATE TABLE IF NOT EXISTS anytype_objects (
 95→          id TEXT PRIMARY KEY,
 96→          space_id TEXT NOT NULL,
 97→          type TEXT,
 98→          title TEXT,
 99→          content TEXT,
100→          data JSONB,
101→          last_modified BIGINT,
102→          synced_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
103→          checksum TEXT,
104→          UNIQUE(space_id, id)
105→        );
106→
107→        CREATE INDEX IF NOT EXISTS idx_anytype_space ON anytype_objects(space_id);
108→        CREATE INDEX IF NOT EXISTS idx_anytype_modified ON anytype_objects(last_modified);
109→        CREATE INDEX IF NOT EXISTS idx_anytype_type ON anytype_objects(type);
110→
111→        CREATE TABLE IF NOT EXISTS anytype_sync_state (
112→          space_id TEXT PRIMARY KEY,
113→          last_synced BIGINT,
114→          last_checked TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
115→          total_objects INT,
116→          new_objects INT,
117→          updated_objects INT
118→        );
119→      `);
120→
121→      this.log('✓ PostgreSQL tables initialized');
122→    } finally {
123→      client.release();
124→    }
125→  }
126→
127→  /**
128→   * List all spaces in the account
129→   */
130→  async listSpaces() {
131→    if (!fs.existsSync(this.config.objectStoreDir)) {
132→      this.log(`Object store directory not found: ${this.config.objectStoreDir}`, 'error');
133→      return [];
134→    }
135→
136→    const spaces = fs.readdirSync(this.config.objectStoreDir)
137→      .filter(name => {
138→        const stat = fs.statSync(path.join(this.config.objectStoreDir, name));
139→        return stat.isDirectory() && name.startsWith('bafyrei');
140→      });
141→
142→    return spaces;
143→  }
144→
145→  /**
146→   * Open SQLite database for a space
147→   */
148→  async openSpaceDb(spaceId) {
149→    return new Promise((resolve, reject) => {
150→      const dbPath = path.join(this.config.objectStoreDir, spaceId, 'objects.db');
151→      
152→      if (!fs.existsSync(dbPath)) {
153→        reject(new Error(`Space database not found: ${dbPath}`));
154→        return;
155→      }
156→
157→      const db = new sqlite3.Database(dbPath, (err) => {
158→        if (err) reject(err);
159→        else resolve(db);
160→      });
161→    });
162→  }
163→
164→  /**
165→   * Get all objects from a space
166→   */
167→  async getSpaceObjects(spaceId) {
168→    const db = await this.openSpaceDb(spaceId);
169→
170→    return new Promise((resolve, reject) => {
171→      db.all(
172→        `SELECT id, data FROM _objects_docs ORDER BY rowid`,
173→        [],
174→        (err, rows) => {
175→          db.close();
176→          if (err) reject(err);
177→          else resolve(rows || []);
178→        }
179→      );
180→    });
181→  }
182→
183→  /**
184→   * Decode object data (handle binary protobuf)
185→   * For now, returns hex representation. In future, would decode proto
186→   */
187→  decodeObjectData(buffer) {
188→    // TODO: Decode protobuf when proto definitions are available
189→    // For now, return metadata about the object
190→    return {
191→      size: buffer.length,
192→      hash: crypto.createHash('sha256').update(buffer).digest('hex').substring(0, 16),
193→      sample: buffer.slice(0, 50).toString('hex') // First 50 hex bytes
194→    };
195→  }
196→
197→  /**
198→   * Sync objects from AnyType space to PostgreSQL
199→   */
200→  async syncSpace(spaceId) {
201→    this.log(`Syncing space: ${spaceId}...`);
202→
203→    try {
204→      const objects = await this.getSpaceObjects(spaceId);
205→      this.log(`Found ${objects.length} objects in space`);
206→
207→      let newCount = 0;
208→      let updatedCount = 0;
209→
210→      for (const obj of objects) {
211→        const id = obj.id.toString('hex');
212→        const metadata = this.decodeObjectData(obj.data);
213→        const checksum = metadata.hash;
214→
215→        // Check if object already exists
216→        const existing = await this.pgPool.query(
217→          'SELECT checksum FROM anytype_objects WHERE space_id = $1 AND id = $2',
218→          [spaceId, id]
219→        );
220→
221→        if (existing.rows.length === 0) {
222→          // New object
223→          await this.pgPool.query(
224→            `INSERT INTO anytype_objects 
225→             (id, space_id, data, checksum, last_modified)
226→             VALUES ($1, $2, $3, $4, $5)`,
227→            [
228→              id,
229→              spaceId,
230→              JSON.stringify(metadata),
231→              checksum,
232→              Date.now()
233→            ]
234→          );
235→          newCount++;
236→        } else if (existing.rows[0].checksum !== checksum) {
237→          // Updated object
238→          await this.pgPool.query(
239→            `UPDATE anytype_objects 
240→             SET data = $1, checksum = $2, synced_at = CURRENT_TIMESTAMP
241→             WHERE space_id = $3 AND id = $4`,
242→            [
243→              JSON.stringify(metadata),
244→              checksum,
245→              spaceId,
246→              id
247→            ]
248→          );
249→          updatedCount++;
250→        }
251→      }
252→
253→      // Update sync state
254→      await this.pgPool.query(
255→        `INSERT INTO anytype_sync_state (space_id, last_synced, total_objects, new_objects, updated_objects)
256→         VALUES ($1, $2, $3, $4, $5)
257→         ON CONFLICT (space_id) DO UPDATE SET
258→           last_synced = $2,
259→           total_objects = $3,
260→           new_objects = $4,
261→           updated_objects = $5,
262→           last_checked = CURRENT_TIMESTAMP`,
263→        [spaceId, Date.now(), objects.length, newCount, updatedCount]
264→      );
265→
266→      this.log(`✓ Synced space: ${newCount} new, ${updatedCount} updated`);
267→      return { newCount, updatedCount, totalCount: objects.length };
268→    } catch (error) {
269→      this.log(`Error syncing space: ${error.message}`, 'error');
270→      throw error;
271→    }
272→  }
273→
274→  /**
275→   * Watch for changes and sync periodically
276→   */
277→  async watchSpaces() {
278→    this.log(`Starting watch mode (interval: ${this.config.pollInterval}ms)`);
279→
280→    // Initial sync
281→    const spaces = await this.listSpaces();
282→    for (const spaceId of spaces) {
283→      await this.syncSpace(spaceId);
284→    }
285→
286→    // Periodic sync
287→    setInterval(async () => {
288→      try {
289→        const spaces = await this.listSpaces();
290→        for (const spaceId of spaces) {
291→          await this.syncSpace(spaceId);
292→        }
293→      } catch (error) {
294→        this.log(`Watch sync error: ${error.message}`, 'error');
295→      }
296→    }, this.config.pollInterval);
297→  }
298→
299→  /**
300→   * Query synced objects from PostgreSQL
301→   */
302→  async queryObjects(filters = {}) {
303→    let query = 'SELECT * FROM anytype_objects WHERE 1=1';
304→    const params = [];
305→    let paramIdx = 1;
306→
307→    if (filters.spaceId) {
308→      query += ` AND space_id = $${paramIdx++}`;
309→      params.push(filters.spaceId);
310→    }
311→
312→    if (filters.type) {
313→      query += ` AND type = $${paramIdx++}`;
314→      params.push(filters.type);
315→    }
316→
317→    if (filters.since) {
318→      query += ` AND last_modified > $${paramIdx++}`;
319→      params.push(filters.since);
320→    }
321→
322→    query += ' ORDER BY last_modified DESC LIMIT $' + paramIdx;
323→    params.push(filters.limit || 50);
324→
325→    const result = await this.pgPool.query(query, params);
326→    return result.rows;
327→  }
328→
329→  /**
330→   * Get sync status
331→   */
332→  async getStatus() {
333→    const result = await this.pgPool.query('SELECT * FROM anytype_sync_state ORDER BY last_checked DESC');
334→    return result.rows;
335→  }
336→
337→  /**
338→   * Cleanup
339→   */
340→  async cleanup() {
341→    if (this.pgPool) {
342→      await this.pgPool.end();
343→    }
344→  }
345→}
346→
347→/**
348→ * CLI interface
349→ */
350→async function cliMain() {
351→  const args = process.argv.slice(2);
352→  const config = {};
353→
354→  // Parse arguments
355→  for (let i = 0; i < args.length; i += 2) {
356→    const key = args[i].replace(/^--/, '');
357→    const value = args[i + 1];
358→
359→    switch (key) {
360→      case 'accountId': config.accountId = value; break;
361→      case 'spaceId': config.spaceId = value; break;
362→      case 'pgUrl': config.pgUrl = value; break;
363→      case 'pollInterval': config.pollInterval = parseInt(value); break;
364→      case 'verbose': config.verbose = true; i--; break;
365→      case 'help':
366→        console.log(`
367→AnyType → PostgreSQL Monitor
368→
369→Syncs AnyType workspace data to PostgreSQL for OpenClaw querying.
370→
371→Usage:
372→  node anytype-monitor.js [options] [command]
373→
374→Commands:
375→  watch (default)      Monitor spaces and sync periodically
376→  list-spaces          List all available spaces
377→  sync-now             Perform one-time sync
378→  status               Show sync status
379→  query <spaceId>      Query synced objects
380→
381→Options:
382→  --accountId <id>     AnyType account ID
383→  --spaceId <id>       Space ID to monitor
384→  --pgUrl <url>        PostgreSQL connection string
385→  --pollInterval <ms>  Polling interval (default: 60000)
386→  --verbose            Enable verbose logging
387→  --help               Show this help message
388→
389→Examples:
390→  node anytype-monitor.js --accountId A6JZ... --spaceId bafyrei... watch
391→  node anytype-monitor.js list-spaces
392→  node anytype-monitor.js --spaceId bafyrei... sync-now
393→  node anytype-monitor.js status
394→
395→Environment variables:
396→  ANYTYPE_ACCOUNT_ID
397→  ANYTYPE_SPACE_ID
398→  DATABASE_URL
399→        `);
400→        process.exit(0);
401→    }
402→  }
403→
404→  try {
405→    const monitor = new AnytypeMonitor(config);
406→    const command = args[0] || 'watch';
407→
408→    // Commands that don't need PostgreSQL
409→    if (command === 'list-spaces') {
410→      const spaces = await monitor.listSpaces();
411→      console.log('Available spaces:');
412→      spaces.forEach(s => console.log(`  ${s}`));
413→      process.exit(0);
414→    }
415→
416→    // Initialize PostgreSQL for other commands
417→    await monitor.initPostgres();
418→
419→    if (command === 'watch') {
420→      await monitor.watchSpaces();
421→      // Keep running
422→      process.on('SIGTERM', async () => {
423→        console.log('\nShutting down...');
