425→        process.exit(0);
426→      });
427→
428→    } else if (command === 'sync-now') {
429→      const spaces = await monitor.listSpaces();
430→      console.log(`Syncing ${spaces.length} spaces...`);
431→      for (const space of spaces) {
432→        const result = await monitor.syncSpace(space);
433→        console.log(`  ${space}: ${result.newCount} new, ${result.updatedCount} updated`);
434→      }
435→      await monitor.cleanup();
436→
437→    } else if (command === 'status') {
438→      const status = await monitor.getStatus();
439→      console.log(JSON.stringify(status, null, 2));
440→      await monitor.cleanup();
441→
442→    } else if (command === 'query') {
443→      if (!args[1]) {
