445→        process.exit(1);
446→      }
447→      const objects = await monitor.queryObjects({ spaceId: args[1] });
448→      console.log(JSON.stringify(objects, null, 2));
449→      await monitor.cleanup();
450→
451→    } else {
452→      console.error(`Unknown command: ${command}`);
