119→   */
120→  async updatePage({ spaceId = this.spaceId, pageId, content, title = null, tags = [] }) {
121→    if (!spaceId) throw new Error('spaceId is required');
122→    if (!pageId) throw new Error('pageId is required');
123→
124→    const payload = {
125→      space: spaceId,
126→      id: pageId,
127→      content: content
128→    };
129→
130→    if (title) {
