143→   */
144→  async getPage({ spaceId = this.spaceId, pageId }) {
145→    if (!spaceId) throw new Error('spaceId is required');
146→    if (!pageId) throw new Error('pageId is required');
147→
148→    return this.request('GET', `/api/v1/objects/${pageId}?space=${spaceId}`);
149→  }
