151→  /**
152→   * Query/search pages in a space
153→   */
154→  async queryPages({ spaceId = this.spaceId, query = '', limit = 50, offset = 0, tags = [] }) {
155→    if (!spaceId) throw new Error('spaceId is required');
156→
157→    const params = new URLSearchParams({
